mapper.select:
SELECT d.analysis_id AS analysisId, d.analysis_date AS analysisDate, d.subbarcode AS subbarcode, d.barcode AS barcode, d.product AS product, d.product_id AS productId, d.analyzer AS analyzer, d.drive_status AS driveStatus, d.drive_executed_at AS driveExecutedAt, r.report_id AS reportId, r.status AS reportStatus, r.analysis_disease AS analysisDisease, r.template_id AS templateId, r.template AS template, r.report_generated_by AS reportGeneratedBy, r.report_generated_at AS reportGeneratedAt FROM analysis_data d LEFT JOIN analysis_report r ON r.report_id = ( SELECT MAX(r2.report_id) FROM analysis_report r2 WHERE r2.analysis_id = d.analysis_id AND r2.del_flag = '0' ) WHERE d.del_flag = '0'
AND d.subbarcode LIKE CONCAT('%', #{query.subbarcode}, '%')
AND d.product LIKE CONCAT('%', #{query.product}, '%')
AND r.status = #{query.reportStatus}
AND d.analysis_date BETWEEN #{beginTime} AND #{endTime}
ORDER BY d.analysis_id DESC

SELECT f.file_id AS fileId, f.file_type AS fileType, f.data_type AS dataType, f.file_name AS fileName, f.file_path AS filePath, f.status AS status, f.message AS message, f.mut_num AS mutNum, f.analysis_date AS analysisDate, CHAR_LENGTH(f.file_text) AS textLength, f.update_time AS updateTime FROM data_file_status f WHERE f.del_flag = '0' AND f.analysis_id = #{analysisId}
AND f.file_name LIKE CONCAT('%', #{query.fileName}, '%')
AND f.file_type LIKE CONCAT('%', #{query.fileType}, '%')
AND f.status = #{query.status}
ORDER BY f.file_id ASC
